7	/**
8	 * Client-side auth configuration for A2A remote agents.
9	 * Corresponds to server-side SecurityScheme types from @a2a-js/sdk.
10	 * @see https://a2a-protocol.org/latest/specification/#451-securityscheme
11	 */
12	
13	import type { AuthenticationHandler } from '@a2a-js/sdk/client';
14	
15	export type A2AAuthProviderType =
16	  | 'google-credentials'
17	  | 'apiKey'
18	  | 'http'
19	  | 'oauth2'
20	  | 'openIdConnect';
21	
22	export interface A2AAuthProvider extends AuthenticationHandler {
23	  readonly type: A2AAuthProviderType;
24	  initialize?(): Promise<void>;
25	}
26	
27	export interface BaseAuthConfig {
28	  agent_card_requires_auth?: boolean;
29	}
30	
31	/** Client config for google-credentials (not in A2A spec, Gemini-specific). */
32	export interface GoogleCredentialsAuthConfig extends BaseAuthConfig {
33	  type: 'google-credentials';
34	  scopes?: string[];
35	}
36	
37	/** Client config corresponding to APIKeySecurityScheme. Only header location is supported. */
38	// TODO: Add 'query' and 'cookie' location support if needed.
39	export interface ApiKeyAuthConfig extends BaseAuthConfig {
40	  type: 'apiKey';
41	  /** The secret. Supports $ENV_VAR, !command, or literal. */
42	  key: string;
43	  /** Header name. @default 'X-API-Key' */
44	  name?: string;
45	}
46	
47	/** Client config corresponding to HTTPAuthSecurityScheme. */
48	export type HttpAuthConfig = BaseAuthConfig & {
49	  type: 'http';
50	} & (
51	    | {
52	        scheme: 'Bearer';
53	        /** For Bearer. Supports $ENV_VAR, !command, or literal. */
54	        token: string;
55	      }
56	    | {
57	        scheme: 'Basic';
58	        /** For Basic. Supports $ENV_VAR, !command, or literal. */
59	        username: string;
60	        /** For Basic. Supports $ENV_VAR, !command, or literal. */
61	        password: string;
62	      }
63	    | {
64	        /** Any IANA-registered scheme (e.g., "Digest", "HOBA", "Custom"). */
65	        scheme: string;
66	        /** Raw value to be sent as "Authorization: <scheme> <value>". Supports $ENV_VAR, !command, or literal. */
67	        value: string;
68	      }
69	  );
70	
71	/** Client config corresponding to OAuth2SecurityScheme. */
72	export interface OAuth2AuthConfig extends BaseAuthConfig {
73	  type: 'oauth2';
74	  client_id?: string;
75	  client_secret?: string;
76	  scopes?: string[];
77	}
78	
79	/** Client config corresponding to OpenIdConnectSecurityScheme. */
80	export interface OpenIdConnectAuthConfig extends BaseAuthConfig {
81	  type: 'openIdConnect';
82	  issuer_url: string;
83	  client_id: string;
84	  client_secret?: string;
85	  target_audience?: string;
86	  scopes?: string[];
87	}
88	
89	export type A2AAuthConfig =
90	  | GoogleCredentialsAuthConfig
91	  | ApiKeyAuthConfig
92	  | HttpAuthConfig
93	  | OAuth2AuthConfig
94	  | OpenIdConnectAuthConfig;
95	
96	export interface AuthConfigDiff {
97	  requiredSchemes: string[];
98	  configuredType?: A2AAuthProviderType;
99	  missingConfig: string[];
100	}
101	
102	export interface AuthValidationResult {
103	  valid: boolean;
104	  diff?: AuthConfigDiff;
105	}
