7	import type { AgentCard, SecurityScheme } from '@a2a-js/sdk';
8	import type {
9	  A2AAuthConfig,
10	  A2AAuthProvider,
11	  AuthValidationResult,
12	} from './types.js';
13	import { ApiKeyAuthProvider } from './api-key-provider.js';
14	import { HttpAuthProvider } from './http-provider.js';
15	
16	export interface CreateAuthProviderOptions {
17	  /** Required for OAuth/OIDC token storage. */
18	  agentName?: string;
19	  authConfig?: A2AAuthConfig;
20	  agentCard?: AgentCard;
21	}
22	
23	/**
24	 * Factory for creating A2A authentication providers.
25	 * @see https://a2a-protocol.org/latest/specification/#451-securityscheme
26	 */
27	export class A2AAuthProviderFactory {
28	  static async create(
29	    options: CreateAuthProviderOptions,
30	  ): Promise<A2AAuthProvider | undefined> {
31	    const { agentName: _agentName, authConfig, agentCard } = options;
32	
33	    if (!authConfig) {
34	      if (
35	        agentCard?.securitySchemes &&
36	        Object.keys(agentCard.securitySchemes).length > 0
37	      ) {
38	        return undefined; // Caller should prompt user to configure auth
39	      }
40	      return undefined;
41	    }
42	
43	    switch (authConfig.type) {
44	      case 'google-credentials':
45	        // TODO: Implement
46	        throw new Error('google-credentials auth provider not yet implemented');
47	
48	      case 'apiKey': {
49	        const provider = new ApiKeyAuthProvider(authConfig);
50	        await provider.initialize();
51	        return provider;
52	      }
53	
54	      case 'http': {
55	        const provider = new HttpAuthProvider(authConfig);
56	        await provider.initialize();
57	        return provider;
58	      }
59	
60	      case 'oauth2':
61	        // TODO: Implement
62	        throw new Error('oauth2 auth provider not yet implemented');
63	
64	      case 'openIdConnect':
65	        // TODO: Implement
66	        throw new Error('openIdConnect auth provider not yet implemented');
67	
68	      default: {
69	        const _exhaustive: never = authConfig;
70	        throw new Error(
71	          `Unknown auth type: ${(_exhaustive as A2AAuthConfig).type}`,
72	        );
73	      }
74	    }
75	  }
76	
77	  /** Create provider directly from config, bypassing AgentCard validation. */
78	  static async createFromConfig(
79	    authConfig: A2AAuthConfig,
80	    agentName?: string,
81	  ): Promise<A2AAuthProvider> {
82	    const provider = await A2AAuthProviderFactory.create({
83	      authConfig,
84	      agentName,
85	    });
86	
87	    // create() returns undefined only when authConfig is missing.
88	    // Since authConfig is required here, provider will always be defined
89	    // (or create() throws for unimplemented types).
90	    return provider!;
91	  }
92	
93	  /** Validate auth config against AgentCard's security requirements. */
94	  static validateAuthConfig(
95	    authConfig: A2AAuthConfig | undefined,
96	    securitySchemes: Record<string, SecurityScheme> | undefined,
97	  ): AuthValidationResult {
98	    if (!securitySchemes || Object.keys(securitySchemes).length === 0) {
99	      return { valid: true };
100	    }
101	
102	    const requiredSchemes = Object.keys(securitySchemes);
103	
104	    if (!authConfig) {
105	      return {
106	        valid: false,
107	        diff: {
108	          requiredSchemes,
109	          configuredType: undefined,
110	          missingConfig: ['Authentication is required but not configured'],
111	        },
112	      };
113	    }
114	
115	    const matchResult = A2AAuthProviderFactory.findMatchingScheme(
116	      authConfig,
117	      securitySchemes,
118	    );
119	
120	    if (matchResult.matched) {
121	      return { valid: true };
122	    }
123	
124	    return {
125	      valid: false,
126	      diff: {
127	        requiredSchemes,
128	        configuredType: authConfig.type,
129	        missingConfig: matchResult.missingConfig,
130	      },
131	    };
132	  }
133	
134	  // Security schemes have OR semantics per A2A spec - matching any single scheme is sufficient
135	  private static findMatchingScheme(
136	    authConfig: A2AAuthConfig,
137	    securitySchemes: Record<string, SecurityScheme>,
138	  ): { matched: boolean; missingConfig: string[] } {
139	    const missingConfig: string[] = [];
140	
141	    for (const [schemeName, scheme] of Object.entries(securitySchemes)) {
142	      switch (scheme.type) {
143	        case 'apiKey':
144	          if (authConfig.type === 'apiKey') {
145	            return { matched: true, missingConfig: [] };
146	          }
147	          missingConfig.push(
148	            `Scheme '${schemeName}' requires apiKey authentication`,
149	          );
150	          break;
151	
152	        case 'http':
153	          if (authConfig.type === 'http') {
154	            if (
155	              authConfig.scheme.toLowerCase() === scheme.scheme.toLowerCase()
156	            ) {
157	              return { matched: true, missingConfig: [] };
158	            }
159	            missingConfig.push(
160	              `Scheme '${schemeName}' requires HTTP ${scheme.scheme} authentication, but ${authConfig.scheme} was configured`,
161	            );
162	          } else if (
163	            authConfig.type === 'google-credentials' &&
164	            scheme.scheme.toLowerCase() === 'bearer'
165	          ) {
166	            return { matched: true, missingConfig: [] };
167	          } else {
168	            missingConfig.push(
169	              `Scheme '${schemeName}' requires HTTP ${scheme.scheme} authentication`,
170	            );
171	          }
172	          break;
173	
174	        case 'oauth2':
175	          if (authConfig.type === 'oauth2') {
176	            return { matched: true, missingConfig: [] };
177	          }
178	          missingConfig.push(
179	            `Scheme '${schemeName}' requires OAuth 2.0 authentication`,
180	          );
181	          break;
182	
183	        case 'openIdConnect':
184	          if (authConfig.type === 'openIdConnect') {
185	            return { matched: true, missingConfig: [] };
186	          }
187	          missingConfig.push(
188	            `Scheme '${schemeName}' requires OpenID Connect authentication`,
189	          );
190	          break;
191	
192	        case 'mutualTLS':
193	          missingConfig.push(
194	            `Scheme '${schemeName}' requires mTLS authentication (not yet supported)`,
195	          );
196	          break;
197	
198	        default: {
199	          const _exhaustive: never = scheme;
200	          missingConfig.push(
201	            `Unknown security scheme type: ${(_exhaustive as SecurityScheme).type}`,
202	          );
203	        }
204	      }
205	    }
206	
207	    return { matched: false, missingConfig };
208	  }
209	
210	  /** Get human-readable description of required auth for error messages. */
211	  static describeRequiredAuth(
212	    securitySchemes: Record<string, SecurityScheme>,
213	  ): string {
214	    const descriptions: string[] = [];
215	
216	    for (const [name, scheme] of Object.entries(securitySchemes)) {
