7	import type { HttpHeaders } from '@a2a-js/sdk/client';
8	import { BaseA2AAuthProvider } from './base-provider.js';
9	import type { HttpAuthConfig } from './types.js';
10	import { resolveAuthValue } from './value-resolver.js';
11	import { debugLogger } from '../../utils/debugLogger.js';
12	
13	/**
14	 * Authentication provider for HTTP authentication schemes.
15	 * Supports Bearer, Basic, and any IANA-registered scheme via raw value.
16	 */
17	export class HttpAuthProvider extends BaseA2AAuthProvider {
18	  readonly type = 'http' as const;
19	
20	  private resolvedToken?: string;
21	  private resolvedUsername?: string;
22	  private resolvedPassword?: string;
23	  private resolvedValue?: string;
24	
25	  constructor(private readonly config: HttpAuthConfig) {
26	    super();
27	  }
28	
29	  override async initialize(): Promise<void> {
30	    const config = this.config;
31	    if ('token' in config) {
32	      this.resolvedToken = await resolveAuthValue(config.token);
33	    } else if ('username' in config) {
34	      this.resolvedUsername = await resolveAuthValue(config.username);
35	      this.resolvedPassword = await resolveAuthValue(config.password);
36	    } else {
37	      // Generic raw value for any other IANA-registered scheme
38	      this.resolvedValue = await resolveAuthValue(config.value);
39	    }
40	    debugLogger.debug(
41	      `[HttpAuthProvider] Initialized with scheme: ${this.config.scheme}`,
42	    );
43	  }
44	
45	  override async headers(): Promise<HttpHeaders> {
46	    const config = this.config;
47	    if ('token' in config) {
48	      if (!this.resolvedToken)
49	        throw new Error('HttpAuthProvider not initialized');
50	      return { Authorization: `Bearer ${this.resolvedToken}` };
51	    }
52	
53	    if ('username' in config) {
54	      if (!this.resolvedUsername || !this.resolvedPassword) {
55	        throw new Error('HttpAuthProvider not initialized');
56	      }
57	      const credentials = Buffer.from(
58	        `${this.resolvedUsername}:${this.resolvedPassword}`,
59	      ).toString('base64');
60	      return { Authorization: `Basic ${credentials}` };
61	    }
62	
63	    // Generic raw value for any other IANA-registered scheme
64	    if (!this.resolvedValue)
65	      throw new Error('HttpAuthProvider not initialized');
66	    return { Authorization: `${config.scheme} ${this.resolvedValue}` };
67	  }
68	
69	  /**
70	   * Re-resolves credentials on auth failure (e.g. rotated tokens via $ENV or !command).
71	   * Respects MAX_AUTH_RETRIES from the base class to prevent infinite loops.
72	   */
73	  override async shouldRetryWithHeaders(
74	    req: RequestInit,
75	    res: Response,
76	  ): Promise<HttpHeaders | undefined> {
77	    if (res.status === 401 || res.status === 403) {
78	      if (this.authRetryCount >= BaseA2AAuthProvider.MAX_AUTH_RETRIES) {
79	        return undefined;
80	      }
81	      debugLogger.debug(
82	        '[HttpAuthProvider] Re-resolving values after auth failure',
83	      );
84	      await this.initialize();
85	    }
86	    return super.shouldRetryWithHeaders(req, res);
87	  }
88	}
