23	/**
24	 * Class for managing MCP OAuth token storage and retrieval.
25	 */
26	export class MCPOAuthTokenStorage implements TokenStorage {
27	  private readonly hybridTokenStorage = new HybridTokenStorage(
28	    DEFAULT_SERVICE_NAME,
29	  );
30	  private readonly useEncryptedFile =
31	    process.env[FORCE_ENCRYPTED_FILE_ENV_VAR] === 'true';
32	
33	  /**
34	   * Get the path to the token storage file.
35	   *
36	   * @returns The full path to the token storage file
37	   */
38	  private getTokenFilePath(): string {
39	    return Storage.getMcpOAuthTokensPath();
40	  }
41	
42	  /**
43	   * Ensure the config directory exists.
44	   */
45	  private async ensureConfigDir(): Promise<void> {
46	    const configDir = path.dirname(this.getTokenFilePath());
47	    await fs.mkdir(configDir, { recursive: true });
48	  }
49	
50	  /**
51	   * Load all stored MCP OAuth tokens.
52	   *
53	   * @returns A map of server names to credentials
54	   */
55	  async getAllCredentials(): Promise<Map<string, OAuthCredentials>> {
56	    if (this.useEncryptedFile) {
57	      return this.hybridTokenStorage.getAllCredentials();
58	    }
59	    const tokenMap = new Map<string, OAuthCredentials>();
60	
61	    try {
62	      const tokenFile = this.getTokenFilePath();
63	      const data = await fs.readFile(tokenFile, 'utf-8');
64	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
65	      const tokens = JSON.parse(data) as OAuthCredentials[];
66	
67	      for (const credential of tokens) {
68	        tokenMap.set(credential.serverName, credential);
69	      }
70	    } catch (error) {
71	      // File doesn't exist or is invalid, return empty map
72	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
73	      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
74	        coreEvents.emitFeedback(
75	          'error',
76	          `Failed to load MCP OAuth tokens: ${getErrorMessage(error)}`,
77	          error,
78	        );
79	      }
80	    }
81	
82	    return tokenMap;
83	  }
84	
85	  async listServers(): Promise<string[]> {
86	    if (this.useEncryptedFile) {
87	      return this.hybridTokenStorage.listServers();
88	    }
89	    const tokens = await this.getAllCredentials();
90	    return Array.from(tokens.keys());
91	  }
92	
93	  async setCredentials(credentials: OAuthCredentials): Promise<void> {
94	    if (this.useEncryptedFile) {
95	      return this.hybridTokenStorage.setCredentials(credentials);
96	    }
97	    const tokens = await this.getAllCredentials();
98	    tokens.set(credentials.serverName, credentials);
99	
100	    const tokenArray = Array.from(tokens.values());
101	    const tokenFile = this.getTokenFilePath();
102	
103	    try {
104	      await fs.writeFile(
105	        tokenFile,
106	        JSON.stringify(tokenArray, null, 2),
107	        { mode: 0o600 }, // Restrict file permissions
108	      );
109	    } catch (error) {
110	      coreEvents.emitFeedback(
111	        'error',
112	        `Failed to save MCP OAuth token: ${getErrorMessage(error)}`,
113	        error,
114	      );
115	      throw error;
116	    }
117	  }
118	
119	  /**
120	   * Save a token for a specific MCP server.
121	   *
122	   * @param serverName The name of the MCP server
123	   * @param token The OAuth token to save
124	   * @param clientId Optional client ID used for this token
125	   * @param tokenUrl Optional token URL used for this token
126	   * @param mcpServerUrl Optional MCP server URL
127	   */
128	  async saveToken(
129	    serverName: string,
130	    token: OAuthToken,
131	    clientId?: string,
132	    tokenUrl?: string,
133	    mcpServerUrl?: string,
134	  ): Promise<void> {
135	    await this.ensureConfigDir();
136	
137	    const credential: OAuthCredentials = {
138	      serverName,
139	      token,
140	      clientId,
141	      tokenUrl,
142	      mcpServerUrl,
143	      updatedAt: Date.now(),
144	    };
145	
146	    if (this.useEncryptedFile) {
147	      return this.hybridTokenStorage.setCredentials(credential);
148	    }
149	    await this.setCredentials(credential);
150	  }
151	
152	  /**
153	   * Get a token for a specific MCP server.
154	   *
155	   * @param serverName The name of the MCP server
156	   * @returns The stored credentials or null if not found
157	   */
158	  async getCredentials(serverName: string): Promise<OAuthCredentials | null> {
159	    if (this.useEncryptedFile) {
160	      return this.hybridTokenStorage.getCredentials(serverName);
161	    }
162	    const tokens = await this.getAllCredentials();
163	    return tokens.get(serverName) || null;
164	  }
165	
166	  /**
167	   * Remove a token for a specific MCP server.
168	   *
169	   * @param serverName The name of the MCP server
170	   */
171	  async deleteCredentials(serverName: string): Promise<void> {
172	    if (this.useEncryptedFile) {
173	      return this.hybridTokenStorage.deleteCredentials(serverName);
174	    }
175	    const tokens = await this.getAllCredentials();
176	
177	    if (tokens.delete(serverName)) {
178	      const tokenArray = Array.from(tokens.values());
179	      const tokenFile = this.getTokenFilePath();
180	
181	      try {
182	        if (tokenArray.length === 0) {
183	          // Remove file if no tokens left
184	          await fs.unlink(tokenFile);
185	        } else {
186	          await fs.writeFile(tokenFile, JSON.stringify(tokenArray, null, 2), {
187	            mode: 0o600,
188	          });
189	        }
190	      } catch (error) {
191	        coreEvents.emitFeedback(
192	          'error',
193	          `Failed to remove MCP OAuth token: ${getErrorMessage(error)}`,
194	          error,
195	        );
196	      }
197	    }
198	  }
199	
200	  /**
201	   * Check if a token is expired.
202	   *
203	   * @param token The token to check
204	   * @returns True if the token is expired
205	   */
206	  isTokenExpired(token: OAuthToken): boolean {
207	    if (!token.expiresAt) {
208	      return false; // No expiry, assume valid
209	    }
210	
211	    // Add a 5-minute buffer to account for clock skew
212	    const bufferMs = 5 * 60 * 1000;
213	    return Date.now() + bufferMs >= token.expiresAt;
214	  }
215	
216	  /**
217	   * Clear all stored MCP OAuth tokens.
218	   */
219	  async clearAll(): Promise<void> {
220	    if (this.useEncryptedFile) {
221	      return this.hybridTokenStorage.clearAll();
222	    }
223	    try {
224	      const tokenFile = this.getTokenFilePath();
225	      await fs.unlink(tokenFile);
226	    } catch (error) {
227	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
228	      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
229	        coreEvents.emitFeedback(
230	          'error',
231	          `Failed to clear MCP OAuth tokens: ${getErrorMessage(error)}`,
232	          error,
233	        );
234	      }
235	    }
236	  }
237	}
